contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        require(msg.sender == address(this), "only self");
        require(address(c).balance == 0, "no ether expected at c");

        uint256 beforeBalance = address(c).balance;

        (bool success,) = address(c).call(
            abi.encodeWithSignature(
                "setL1BlockValues(uint64,uint64,uint256,bytes32,uint64,bytes32,uint256,uint256)",
                _number,
                _timestamp,
                _basefee,
                _hash,
                _sequenceNumber,
                _batcherHash,
                _l1FeeOverhead,
                _l1FeeScalar
            )
        );

        uint256 afterBalance = address(c).balance;

        assert(
            success == false ?
            (
                c.number() == 0 &&
                c.timestamp() == 0 &&
                c.basefee() == 0 &&
                c.hash() == bytes32(0) &&
                c.sequenceNumber() == 0 &&
                c.batcherHash() == bytes32(0) &&
                c.l1FeeOverhead() == 0 &&
                c.l1FeeScalar() == 0 &&
                afterBalance == beforeBalance
            ) : (
                c.number() == _number &&
                c.timestamp() == _timestamp &&
                c.basefee() == _basefee &&
                c.hash() == _hash &&
                c.sequenceNumber() == _sequenceNumber &&
                c.batcherHash() == _batcherHash &&
                c.l1FeeOverhead() == _l1FeeOverhead &&
                c.l1FeeScalar() == _l1FeeScalar &&
                afterBalance == beforeBalance
            )
        );
    }

    receive() external payable {}
}

